#!/bin/bash
# Task 077 -- meshsim v1.2, the combined branch (WORKER4: v1.2-meshsim with v1.2-sort merged, at a486b77): before the freeze.
#  1. run_tests.sh's quick suite (34 Java steps: every suite, the recipes and the sort's P1, sort, sort-shuf), 8 at a time;
#  2. its full-mode extras (CtrlTest/AccountingTest/ReadPortGatherTest/EngineTest full, the sweep, AgBench, the skew
#     table, S1Bench, the sort's two BT runs at 64 x 16,384), 4 at a time;
#  3. one full-size sort: WORKER8/runner's run_p4.sh, p4/uniform-k128 at 64 x 65,536 (the kit rebuilt on this branch).
# The kit (wip/ with Java 17 classes and prebuilt images; sortrunner/ = WORKER8/runner) is embedded below, SHA-256
# checked; smoke-tested locally (RecipeTest, SortTest p1, KeyGen; run_p4.sh at n = 2,000). Commits every log and the
# verdicts. Expected 60-120 min, about 32 GB.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/077-meshsim-v12-combined; mkdir -p "$RES"
WANT=a2c699fb3fc50bf80a6fc7126e559a3371bc0624cec0d73407ad58259e4d640f
W=/tmp/ms-077; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/wip/meshsim" || exit 2
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
cd "$W/sortrunner" || exit 2
printf 'p4/uniform-k128\n' > "$W/p4list"
bash ./run_p4.sh -j 1 -m 6g -l "$W/p4list" "$W/p4"; RS=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF, run_p4.sh exit $RS at $(date -u)"
mkdir -p "$RES/p4"; cp "$W"/out/* "$RES/" 2>/dev/null; cp "$W"/p4/* "$RES/p4/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" "$W/p4/VERDICT.txt" 2>/dev/null
[ $RQ = 0 ] && [ $RF = 0 ] && [ $RS = 0 ]
